import { inject, Injectable, signal } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';

/** The booking in progress: the screening and the identifiers of the selected seats (a couch has two). */
export interface Booking {
  screeningId: number;
  seats: string[];
}

const STORAGE_KEY = 'cinescope.booking';

/** Holds the booking in progress and keeps it in `sessionStorage`, so it survives a reload. */
@Injectable({ providedIn: 'root' })
export class BookingStore {
  private readonly current = signal<Booking | null>(readStoredBooking());

  readonly booking = this.current.asReadonly();

  /** Starts an empty booking for the screening, unless the booking in progress already belongs to it. */
  openFor(screeningId: number): void {
    if (this.current()?.screeningId !== screeningId) {
      this.save({ screeningId, seats: [] });
    }
  }

  setSeats(seats: string[]): void {
    const booking = this.current();
    if (booking !== null) {
      this.save({ ...booking, seats });
    }
  }

  clear(): void {
    this.current.set(null);
    sessionStorage.removeItem(STORAGE_KEY);
  }

  private save(booking: Booking): void {
    this.current.set(booking);
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }
}

/**
 * Lets a route with an `id` parameter be entered only with a booking in progress for that
 * screening that has at least one seat; otherwise redirects to the movie list.
 */
export const bookingGuard: CanActivateFn = (route) => {
  const booking = inject(BookingStore).booking();
  const screeningId = Number(route.paramMap.get('id'));
  const allowed = booking !== null && booking.screeningId === screeningId && booking.seats.length > 0;
  return allowed ? true : inject(Router).createUrlTree(['/']);
};

function readStoredBooking(): Booking | null {
  try {
    const stored: unknown = JSON.parse(sessionStorage.getItem(STORAGE_KEY) ?? 'null');
    return isBooking(stored) ? stored : null;
  } catch {
    return null;
  }
}

function isBooking(value: unknown): value is Booking {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const { screeningId, seats } = value as Partial<Booking>;
  return typeof screeningId === 'number' && Array.isArray(seats) && seats.every((id) => typeof id === 'string');
}

import { seatIdentifier } from '../seat-selection/auditorium';

const COUCH_ROW = 15;
const COUCH_PRICE = 89;

/** One line of the booking: a single seat, or a couch covering two adjacent columns of row 15. */
export type Ticket =
  | { kind: 'seat'; row: number; column: number }
  | { kind: 'couch'; row: number; start: number; end: number };

/** The tickets of a booking, ordered by row and then by column. */
export function ticketsFor(seats: readonly string[]): Ticket[] {
  const positions = seats
    .map((id) => {
      const [row, column] = id.slice(1).split('C').map(Number);
      return { row, column };
    })
    .sort((a, b) => a.row - b.row || a.column - b.column);

  const tickets: Ticket[] = [];
  for (const { row, column } of positions) {
    if (row !== COUCH_ROW) {
      tickets.push({ kind: 'seat', row, column });
    } else if (column % 2 === 1) {
      // Row 15 holds only couches, which start at an odd column; the second identifier of each is skipped.
      tickets.push({ kind: 'couch', row, start: column, end: column + 1 });
    }
  }
  return tickets;
}

/** The seat identifiers a ticket occupies: one for a seat, two for a couch. */
export function identifiersOfTicket(ticket: Ticket): string[] {
  return ticket.kind === 'seat'
    ? [seatIdentifier(ticket.row, ticket.column)]
    : [seatIdentifier(ticket.row, ticket.start), seatIdentifier(ticket.row, ticket.end)];
}

/** The seat description: the column of a seat, `Couch <a>-<b>` for a couch. */
export function describeTicket(ticket: Ticket): string {
  return ticket.kind === 'seat' ? String(ticket.column) : `Couch ${ticket.start}-${ticket.end}`;
}

/** The price in PLN: by row for a seat, per couch for a couch. */
export function priceOf(ticket: Ticket): number {
  if (ticket.kind === 'couch') {
    return COUCH_PRICE;
  }
  if (ticket.row <= 5) {
    return 25;
  }
  if (ticket.row <= 10) {
    return 32;
  }
  return 39;
}

/** Formats an amount in PLN with two decimals, e.g. `25.00 PLN`. */
export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

import { Component, computed, effect, inject, resource } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { MatButton } from '@angular/material/button';
import { ActivatedRoute, Router } from '@angular/router';
import { firstValueFrom } from 'rxjs';
import { BookingStore } from '../booking/booking';
import { describeTicket, formatPrice, identifiersOfTicket, priceOf, Ticket, ticketsFor } from '../booking/tickets';
import { CinemaApi } from '../cinema-api';

@Component({
  selector: 'app-summary',
  imports: [MatButton],
  templateUrl: './summary.html',
  styleUrl: './summary.scss',
})
export class Summary {
  private readonly api = inject(CinemaApi);
  private readonly bookings = inject(BookingStore);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  private readonly params = toSignal(this.route.paramMap, { requireSync: true });
  private readonly screeningId = computed(() => Number(this.params().get('id')));

  protected readonly data = resource({
    params: () => this.screeningId(),
    loader: async ({ params: id }) => {
      const screening = await firstValueFrom(this.api.getScreening(id));
      const movie = await firstValueFrom(this.api.getMovie(screening.movieId));
      return { screening, movie };
    },
  });

  protected readonly lines = computed(() =>
    ticketsFor(this.bookings.booking()?.seats ?? []).map((ticket) => ({
      key: identifiersOfTicket(ticket).join(' '),
      ticket,
      description: describeTicket(ticket),
      price: priceOf(ticket),
    })),
  );

  protected readonly total = computed(() =>
    formatPrice(this.lines().reduce((sum, line) => sum + line.price, 0)),
  );

  protected readonly formatPrice = formatPrice;

  constructor() {
    // A screening or movie that cannot be loaded sends the customer back to the movie list.
    effect(() => {
      if (this.data.error()) {
        void this.router.navigate(['/']);
      }
    });
  }

  protected remove(ticket: Ticket): void {
    const removed = identifiersOfTicket(ticket);
    const remaining = (this.bookings.booking()?.seats ?? []).filter((id) => !removed.includes(id));
    this.bookings.setSeats(remaining);
    if (remaining.length === 0) {
      this.openSeatMap();
    }
  }

  protected onBack(): void {
    this.openSeatMap();
  }

  protected onConfirm(): void {
    void this.router.navigate(['/screenings', this.screeningId(), 'checkout']);
  }

  private openSeatMap(): void {
    void this.router.navigate(['/screenings', this.screeningId(), 'seats']);
  }
}

